    if not reason:
        raise BillingError("reason_required", "a reason is required")
    if len(reason) > MAX_REASON_LENGTH:
        raise BillingError("reason_too_long", str(len(reason)))

    note = {"invoice_id": invoice.id, "amount": amount, "reason": reason}
    audit.record(
        "credit_note_issued",
        invoice_id=invoice.id,
        amount=amount,
        reason=reason,
        idempotency_key=idempotency_key,
    )
    return note
EOF
