from decimal import Decimal
from ledgerly import audit
from ledgerly.adjustments import issue_credit_note
from ledgerly.errors import BillingError
from ledgerly.models import Invoice, LineItem

def inv(status="issued"):
    return Invoice("inv_1","cus_1",lines=[LineItem("Seat",1,Decimal("50.00"))],status=status)

# basic
n = issue_credit_note(inv(), Decimal("10.00"), "goodwill")
print("basic", n)
# idempotency
n2 = issue_credit_note(inv(), Decimal("10.00"), "goodwill", idempotency_key="k1")
n3 = issue_credit_note(inv(), Decimal("99.00"), "different", idempotency_key="k1")
print("idem", n2, n3, len(audit.events("credit_note_issued")))
# errors
for args in [(Decimal("0"),"x"),(Decimal("-1"),"x"),(Decimal("50.01"),"x"),(Decimal("1"),"")]:
    try:
        issue_credit_note(inv(), *args); print("NO ERROR", args)
    except BillingError as e: print("err", e.code)
try:
    issue_credit_note(inv("draft"), Decimal("1"), "x")
except BillingError as e: print("err", e.code)
try:
    issue_credit_note(inv(), Decimal("1"), "x"*201)
except BillingError as e: print("err", e.code)
# exact total ok
print("exact", issue_credit_note(inv(), Decimal("50.00"), "full"))
EOF"}

